export const BatchSchema = type({
  id: 'string',
  object: type("'batch'").describe('The object type, which is always `batch`.'),
  endpoint: type('string').describe('The OpenAI API endpoint used by the batch.'),
  'model?': type('string').describe(
    'Model ID used to process the batch, like `gpt-6.2-astra`. OpenAI\noffers a wide range of models with different capabilities, performance\ncharacteristics, and price points. Refer to the [model\nguide](https://developers.openai.com/api/docs/models) to browse and compare available models.\n',
  ),
  'errors?': type(
    type({
      'object?': type('string').describe('The object type, which is always `list`.'),
      'data?': type(BatchErrorSchema).array(),
    }),
  ).or('null'),
  input_file_id: type('string').describe('The ID of the input file for the batch.'),
  completion_window: type('string').describe(
    'The time frame within which the batch should be processed.',
  ),
  status: type(
    "'validating' | 'failed' | 'in_progress' | 'finalizing' | 'completed' | 'expired' | 'cancelling' | 'cancelled'",
  ).describe('The current status of the batch.'),
  'output_file_id?': type('string | null').describe(
    'The ID of the file containing the outputs of successfully executed requests.',
  ),
  'error_file_id?': type('string | null').describe(
    'The ID of the file containing the outputs of requests with errors.',
  ),
  created_at: type('number.integer').describe(
    'The Unix timestamp (in seconds) for when the batch was created.',
  ),
  'in_progress_at?': type('number.integer | null').describe(
    'The Unix timestamp (in seconds) for when the batch started processing.',
  ),
  'expires_at?': type('number.integer | null').describe(
    'The Unix timestamp (in seconds) for when the batch will expire.',
  ),
  'finalizing_at?': type('number.integer | null').describe(
    'The Unix timestamp (in seconds) for when the batch started finalizing.',
  ),
  'completed_at?': type('number.integer | null').describe(
    'The Unix timestamp (in seconds) for when the batch was completed.',
  ),
  'failed_at?': type('number.integer | null').describe(
    'The Unix timestamp (in seconds) for when the batch failed.',
  ),
  'expired_at?': type('number.integer | null').describe(
    'The Unix timestamp (in seconds) for when the batch expired.',
  ),
  'cancelling_at?': type('number.integer | null').describe(
    'The Unix timestamp (in seconds) for when the batch started cancelling.',
  ),
  'cancelled_at?': type('number.integer | null').describe(
    'The Unix timestamp (in seconds) for when the batch was cancelled.',
  ),
  'request_counts?': BatchRequestCountsSchema,
  'usage?': type({
    input_tokens: type('number.integer').describe('The number of input tokens.'),
    input_tokens_details: type({
      cached_tokens: type('number.integer').describe(
        'The number of tokens that were retrieved from the cache. [More on\nprompt caching](https://developers.openai.com/api/docs/guides/prompt-caching).\n',
      ),
    }).describe('A detailed breakdown of the input tokens.'),
    output_tokens: type('number.integer').describe('The number of output tokens.'),
    output_tokens_details: type({
      reasoning_tokens: type('number.integer').describe('The number of reasoning tokens.'),
    }).describe('A detailed breakdown of the output tokens.'),
    total_tokens: type('number.integer').describe('The total number of tokens used.'),
  }).describe(
    'Represents token usage details including input tokens, output tokens, a\nbreakdown of output tokens, and the total tokens used. Only populated on\nbatches created after September 7, 2025.\n',
  ),
  'metadata?': MetadataSchema,
})

export type BatchSchema = typeof BatchSchema.infer

export const BatchFileExpirationAfterSchema = type({
  anchor: type("'created_at'").describe(
    'Anchor timestamp after which the expiration policy applies. Supported anchors: `created_at`. Note that the anchor is the file creation time, not the time the batch is created.',
  ),
  seconds: type('bigint | number.integer')
    .or(/^-?\d+$/)
    .pipe((data) => BigInt(data))
    .narrow(
      (data, ctx) =>
        (data >= -9223372036854775808n && data <= 9223372036854775807n) || ctx.mustBe('an int64'),
    )
    .narrow((data, ctx) => data >= 3600n || ctx.mustBe('at least 3600'))
    .narrow((data, ctx) => data <= 2592000n || ctx.mustBe('at most 2592000'))
    .describe(
      'The number of seconds after the anchor time that the file will expire. Must be between 3600 (1 hour) and 2592000 (30 days).',
    ),
}).describe(
  'The expiration policy for the output and/or error file that are generated for a batch.',
)

export type BatchFileExpirationAfterSchema = typeof BatchFileExpirationAfterSchema.infer

