export const FileExpirationAfterSchema = type({
  anchor: type("'created_at'").describe(
    'Anchor timestamp after which the expiration policy applies. Supported anchors: `created_at`.',
  ),
  seconds: type('bigint | number.integer')
    .or(/^-?\d+$/)
    .pipe((data) => BigInt(data))
    .narrow(
      (data, ctx) =>
        (data >= -9223372036854775808n && data <= 9223372036854775807n) || ctx.mustBe('an int64'),
    )
    .narrow((data, ctx) => data >= 3600n || ctx.mustBe('at least 3600'))
    .narrow((data, ctx) => data <= 2592000n || ctx.mustBe('at most 2592000'))
    .describe(
      'The number of seconds after the anchor time that the file will expire. Must be between 3600 (1 hour) and 2592000 (30 days).',
    ),
}).describe(
  'The expiration policy for a file. By default, files with `purpose=batch` expire after 30 days and all other files are persisted until they are manually deleted.',
)

export type FileExpirationAfterSchema = typeof FileExpirationAfterSchema.infer

