export const LiveAllowedServerEventParamSchema = type({
  type: type('string')
    .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'))
    .narrow((data, ctx) => [...data].length <= 256 || ctx.mustBe('at most 256 characters'))
    .describe("The outer Live server event type. Use 'response.event' for Responses events."),
  'response_event?': type('string')
    .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'))
    .narrow((data, ctx) => [...data].length <= 256 || ctx.mustBe('at most 256 characters'))
    .describe(
      "The nested Responses event type. Required when type is 'response.event'; forbidden for other event types.",
    ),
  '+': 'reject',
}).describe('A Live server event selector for the WebRTC frontend data channel.')

export type LiveAllowedServerEventParamSchema = typeof LiveAllowedServerEventParamSchema.infer

export const LiveDataChannelConfigParamSchema = type({
  'allowed_client_events?': type("'all'")
    .or(
      type(
        type(
          type('string')
            .and(/^(?:error|info|[a-z][a-z0-9_-]*(?:\.[a-z0-9_-]+)+)$/)
            .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'))
            .narrow((data, ctx) => [...data].length <= 256 || ctx.mustBe('at most 256 characters'))
            .describe(
              'A Live client event type allowed on the frontend data channel, such as `session.input_audio.mute`.',
            ),
        ).array(),
      ).and(type('unknown[] <= 256')),
    )
    .describe(
      "Client event types that the frontend data channel may send. Use 'all' to allow every client event; an empty array allows none. Omission preserves the existing allow-all behavior.",
    ),
  'allowed_server_events?': type("'all'")
    .or(type(type(LiveAllowedServerEventParamSchema).array()).and(type('unknown[] <= 256')))
    .describe(
      "Server events that may be sent to the frontend data channel. Use 'all' to allow every server event; an empty array allows none. Omission preserves the existing allow-all behavior. Responses events use an object with type 'response.event' and a response_event selector.",
    ),
}).describe(
  'Control which Live events an untrusted WebRTC frontend can send and receive over its data channel. These restrictions do not apply to trusted sideband connections.',
)

export type LiveDataChannelConfigParamSchema = typeof LiveDataChannelConfigParamSchema.infer

export const LiveClientConfigParamSchema = type({
  data_channel: LiveDataChannelConfigParamSchema.describe(
    'Client and server event permissions for the WebRTC frontend data channel.',
  ),
}).describe(
  'Startup-only capabilities for an untrusted frontend attached to a unified WebRTC session. Trusted sideband connections are unaffected.',
)

export type LiveClientConfigParamSchema = typeof LiveClientConfigParamSchema.infer

export const LiveSessionCreateParamsSchema = type({
  model: ModelIdsLiveSchema,
  'safety_identifier?': type(
    type('string')
      .narrow((data, ctx) => [...data].length <= 128 || ctx.mustBe('at most 128 characters'))
      .describe(
        'A stable identifier for your end user, used for safety monitoring and abuse detection.',
      ),
  ).or('null'),
  'instructions?': type(
    type('string').describe(
      'Frontend instructions for voice, conversation, interruptions, and when to delegate. Start with the [Live prompting guide](https://developers.openai.com/api/docs/guides/live-prompting); put business rules and tool workflows in a separate [backend prompt](https://developers.openai.com/api/docs/guides/live-delegation#start-with-your-existing-backend-prompt). Limited to 16,384 client-supplied tokens. Omitted or blank instructions use server defaults. Immutable after startup.',
    ),
  ).or('null'),
  'input?': type(type(LiveInitialItemSchema).array())
    .and(type('unknown[] <= 128'))
    .describe(
      'Ordered text-only history supplied before startup. Supports developer, user, and assistant messages with one text part each; at most 128 messages and a configured rendered-token limit (8,192 by default).',
    ),
  'audio?': LiveInitialSessionAudioParamSchema.describe(
    'Startup audio configuration. Only primary WebSockets accept audio.format; WebRTC and SIP negotiate their media format. Voice and format are immutable after startup.',
  ),
  'delegation?': type(
    type(
      type(type(LiveClientDelegationParamSchema).and({ type: "'LiveClientDelegationParam'" })).or(
        type(LiveResponsesDelegationParamSchema).and({ type: "'LiveResponsesDelegationParam'" }),
      ),
    )
      .or(type(LiveDecisionsDelegationParamSchema).and({ type: "'LiveDecisionsDelegationParam'" }))
      .describe(
        'Who handles tasks delegated by the Live model. Omitted or null selects your application; use `responses` or `decisions` to delegate to the corresponding API.',
      ),
  ).or('null'),
  'triggers?': type(type(LiveDecisionTriggerInputParamSchema).array())
    .and(type('unknown[] <= 2'))
    .describe(
      'At most one Decisions trigger per transcript event type. Triggers run independently of delegation. On update, omit triggers to keep the current configuration, send a list to replace it, or send an empty list to disable triggers.',
    ),
  'store?': type('boolean').describe(
    'Whether to store the session for later forking and recording download. Defaults to false for new sessions.',
  ),
  'client?': LiveClientConfigParamSchema.describe(
    'Startup-only capabilities for an untrusted frontend attached to a unified WebRTC session. Trusted sideband connections are unaffected.',
  ),
}).describe(
  'Initial configuration for a Live session, including its model, conversation instructions, audio, and delegated task handling.',
)

export type LiveSessionCreateParamsSchema = typeof LiveSessionCreateParamsSchema.infer

