export const ResponseSteerAcceptedEventSchema = type({
  type: type("'response.steer.accepted'").describe(
    'The event discriminator. Always `response.steer.accepted`.',
  ),
  sequence_number: type('number.integer').describe('The sequence number for this event.'),
  steer: type({
    id: type('string').describe('The ID assigned to the steering submission.'),
    previous_response_id: type('string').describe('The ID of the response being steered.'),
  }).describe('The accepted steering submission.'),
  'stream_id?': type('string').describe(
    "The WebSocket lane that emitted this event. This field is present when\nthe target response's `response.create` event supplied a `stream_id`.\n",
  ),
}).describe(
  "Emitted when steering input has been validated and queued. Acceptance means\nthe server owns the input, not that it has been applied. The successor's\n`response.created` event is the commit point. If accepted input cannot be\ncommitted, `response.steer.failed` returns it with the same steering ID.\n\nWhen the response stops for client-owned tool output or approval, the input\nremains queued and `response.steer.pending` is emitted after\n`response.completed`. Fill the pending event's `required_input` stubs with\nsaved results and send one matching explicit `response.create` per parent.\nDo not resend accepted input while it is still queued.\n",
)

export type ResponseSteerAcceptedEventSchema = typeof ResponseSteerAcceptedEventSchema.infer

export const ResponseSteerErrorCodeSchema = type(
  "'response_not_found' | 'invalid_input' | 'steering_not_supported' | 'too_many_pending_steers' | 'response_already_completed' | 'response_not_active' | 'successor_creation_failed' | string",
).describe(
  'A machine-readable steering error code. Clients should handle unknown\nvalues because additional codes may be introduced. Known values include:\n- `response_not_found`: The target response is not available on this connection.\n- `invalid_input`: The event or input failed validation.\n- `steering_not_supported`: The model or response execution mode does not support steering.\n- `too_many_pending_steers`: Too much steering input is pending for the response.\n- `response_already_completed`: The response completed and is no longer accepting steering input.\n- `response_not_active`: The response is no longer accepting steering input.\n- `successor_creation_failed`: The successor response could not be created.\n',
)

export type ResponseSteerErrorCodeSchema = typeof ResponseSteerErrorCodeSchema.infer

export const UserMessageItemParamSchema = type({
  'id?': type(type('string').describe('The unique ID of this message item.')).or('null'),
  type: type("'message'").describe('The item type. Always `message`.'),
  role: type("'user'").describe('The message role. Always `user`.'),
  content: type(
    type(
      type(
        type(type(InputTextContentParamSchema).and({ type: "'InputTextContentParam'" })).or(
          type(InputImageContentParamAutoParamSchema).and({
            type: "'InputImageContentParamAutoParam'",
          }),
        ),
      )
        .or(type(InputFileContentParamSchema).and({ type: "'InputFileContentParam'" }))
        .describe('A piece of message content, such as text, an image, or a file.'),
    ).array(),
  )
    .or(
      type('string')
        .narrow(
          (data, ctx) => [...data].length <= 10485760 || ctx.mustBe('at most 10485760 characters'),
        )
        .describe('The message content, as a single string.'),
    )
    .describe('The message content, as an array of content parts.'),
  'status?': type(type('string').describe('The status of the message item.')).or('null'),
})

export type UserMessageItemParamSchema = typeof UserMessageItemParamSchema.infer

export const ResponseSteerInputItemSchema = type(UserMessageItemParamSchema).or(
  FunctionCallOutputItemParamSchema,
)

export type ResponseSteerInputItemSchema = typeof ResponseSteerInputItemSchema.infer

export const ResponseSteerInputItemListSchema = type(type(ResponseSteerInputItemSchema).array())
  .and(type('unknown[] >= 1'))
  .describe('A non-empty list of message inputs to queue for the response.')

export type ResponseSteerInputItemListSchema = typeof ResponseSteerInputItemListSchema.infer

export const ResponseSteerInputSchema = type(
  type('string').describe('A text input, equivalent to a message with the `user` role.'),
)
  .or(ResponseSteerInputItemListSchema)
  .describe(
    'Input to queue for a continuation of the response. Uses the same string or\ninput-item shape as `response.create.input`, with a non-empty array when\nsupplying input items.\n\nSteering accepts only messages with the `user` role. Each message may\ncontain only `type`, `role`, and `content`, with `content` as a string or an\narray of `input_text`, `input_image`, and `input_file` parts. The optional\n`type` must be `message`. Other roles, tool outputs, and item types are not\nsupported for steering.\n',
  )

export type ResponseSteerInputSchema = typeof ResponseSteerInputSchema.infer

export const ResponseSteerEventSchema = type({
  type: type("'response.steer'").describe('The event discriminator. Always `response.steer`.'),
  previous_response_id: type('string').describe(
    'The ID of the response to steer on this WebSocket connection.',
  ),
  input: ResponseSteerInputSchema,
  '+': 'reject',
}).describe(
  "Queues user input to steer a response on this WebSocket connection. Input\ncan contain text, images, and files. Steering is supported only for\nsingle-agent responses on models and execution modes that support steering.\nResponses bound to a conversation or using automatic compaction do not\nsupport steering.\n\nA `response.steer.accepted` event acknowledges that the server owns the\nqueued input, not that it has been applied. The successor's `response.created`\nevent is the commit point. Input that cannot be committed is returned in\n`response.steer.failed`.\n\nSteering may cause the active response to finish at a safe output boundary\nwith `response.incomplete` and `incomplete_details.reason` set to `steered`,\nfollowed automatically by a successor `response.created`. Normal completion\ncan also be followed by an automatic successor. Automatic successors inherit\nthe previous response's settings and continue from it with the queued input.\n\nIf the response stops for client-owned tool output or approval, accepted\nsteering input remains queued and `response.steer.pending` is emitted after\n`response.completed`. Fill the `required_input` stubs from that event with\nsaved tool results or approval decisions, and send one explicit\n`response.create` per parent with the same `previous_response_id` and\nWebSocket lane. Do not rerun tools or resend accepted steering input. The\nqueued input is prepended in submission order to that request's input, and\nthe explicit request retains its own settings.\n\nThis event accepts only `type`, `previous_response_id`, and `input`. Do not\nsend `stream_id`; the target response determines the WebSocket lane.\n",
)

export type ResponseSteerEventSchema = typeof ResponseSteerEventSchema.infer

export const ResponseSteerFailedEventSchema = type({
  type: type("'response.steer.failed'").describe(
    'The event discriminator. Always `response.steer.failed`.',
  ),
  sequence_number: type('number.integer').describe('The sequence number for this event.'),
  steer: type({
    'id?': type('string').describe(
      'The ID assigned to the steering submission, if one was allocated.\n',
    ),
    previous_response_id: type('string').describe(
      'The ID of the response that was targeted for steering.',
    ),
    input: ResponseSteerInputSchema,
  }).describe('The steering submission that could not be committed.'),
  error: type({
    type: type("'invalid_request_error'").describe(
      'The error type. Always `invalid_request_error`.',
    ),
    code: ResponseSteerErrorCodeSchema,
    message: type('string').describe('A human-readable description of the error.'),
  }).describe('Information about why the input could not be committed.'),
  'stream_id?': type('string').describe(
    'The WebSocket lane that emitted this event, when the target response is\navailable and its `response.create` event supplied a `stream_id`.\n',
  ),
}).describe(
  'Emitted when steering input is rejected or cannot be committed to a\nsuccessor response. Returns the original, uncommitted input so the client\ncan carry it into `response.create` when appropriate. Invalid input must\nbe corrected before retrying.\n\nFailures after acceptance include the same steering ID. Failures before an\nID is allocated omit `steer.id`. A lost connection or missing acknowledgement\nleaves the outcome unknown; it is not proof that the input was rejected.\n',
)

export type ResponseSteerFailedEventSchema = typeof ResponseSteerFailedEventSchema.infer

export const ResponseSteerPendingReasonSchema = type(
  "'waiting_for_required_input' | string",
).describe(
  'An extensible enum describing why accepted steering input is still queued.\nClients should handle unknown values because additional reasons may be\nintroduced. Known values include:\n- `waiting_for_required_input`: The response is waiting for the tool results or approval decisions identified by `required_input`.\n',
)

export type ResponseSteerPendingReasonSchema = typeof ResponseSteerPendingReasonSchema.infer

export const ResponseSteerRequiredInputSchema = type(
  type(
    type(
      type(
        type(
          type(
            type({
              type: "'function_call_output'",
              call_id: 'string',
              name: 'string',
              '+': 'reject',
            }).describe('Supply `output` using the function tool call output input schema.\n'),
          ).or(
            type({ type: "'custom_tool_call_output'", call_id: 'string', '+': 'reject' }).describe(
              "Supply `output` using the custom tool call output input schema. The\noriginal custom tool call supplies the tool's name.\n",
            ),
          ),
        ).or(
          type({ type: "'computer_call_output'", call_id: 'string', '+': 'reject' }).describe(
            'Supply `output` using the computer tool call output input schema,\nincluding any required `acknowledged_safety_checks`.\n',
          ),
        ),
      ).or(
        type({ type: "'shell_call_output'", call_id: 'string', '+': 'reject' }).describe(
          'Supply `output` using the shell tool call output input schema. Each\noutput entry includes `stdout`, `stderr`, and `outcome`.\n',
        ),
      ),
    ).or(
      type({ type: "'apply_patch_call_output'", call_id: 'string', '+': 'reject' }).describe(
        'Supply `status` and optional `output` using the apply patch tool call\noutput input schema.\n',
      ),
    ),
  ).or(
    type({
      type: "'tool_search_output'",
      call_id: 'string',
      execution: "'client'",
      '+': 'reject',
    }).describe(
      'Supply `tools` using the tool search output input schema, retaining\n`execution: "client"`.\n',
    ),
  ),
)
  .or(
    type({
      type: "'mcp_approval_response'",
      approval_request_id: 'string',
      '+': 'reject',
    }).describe(
      'Supply `approve` using the MCP approval response input schema. An\noptional `reason` can be supplied when denying the request. The original\napproval request identifies the tool and server.\n',
    ),
  )
  .describe(
    'An input stub identifying an outstanding client-owned tool result or\napproval decision. Copy the stub and fill the result fields using the\ncorresponding `response.create` input schema. Use saved results without\nrerunning the tool. The server does not supply results, approval decisions,\nor safety acknowledgements in these stubs.\n',
  )

export type ResponseSteerRequiredInputSchema = typeof ResponseSteerRequiredInputSchema.infer

export const ResponseSteerPendingEventSchema = type({
  type: type("'response.steer.pending'").describe(
    'The event discriminator. Always `response.steer.pending`.',
  ),
  sequence_number: type('number.integer').describe('The sequence number for this event.'),
  steer: type({
    id: type('string').describe('The ID assigned to the steering submission.'),
    previous_response_id: type('string').describe('The ID of the response being steered.'),
  }).describe('The steering submission that remains queued.'),
  reason: ResponseSteerPendingReasonSchema,
  required_input: type(type(ResponseSteerRequiredInputSchema).array())
    .and(type('unknown[] >= 1'))
    .describe(
      'Input stubs identifying outstanding client-owned tool results or\napproval decisions. Each stub contains identifying fields only; the\nclient supplies the result before including it in `response.create`.\n',
    ),
  'stream_id?': type('string').describe(
    "The WebSocket lane that emitted this event. This field is present when\nthe target response's `response.create` event supplied a `stream_id`.\n",
  ),
}).describe(
  "Emitted when accepted steering input remains queued after the target\nresponse completes. The server still owns the input. Do not resend it.\nThe successor's `response.created` event is the commit point.\n\nWhen `reason` is `waiting_for_required_input`, this event follows\n`response.completed` while the response waits for the tool results or\napproval decisions identified by `required_input`. Copy those stubs, fill\ntheir result fields using the ordinary `response.create` input schemas,\nand submit one continuation per parent with the same `previous_response_id`\nand WebSocket lane. Use saved results without rerunning tools. The queued\nsteering input is prepended in submission order to the continuation's\ninput. That explicit request retains its own settings.\n\nThis notification is emitted at most once per steering submission. Multiple\nsubmissions for the same parent can report the same required inputs; they\ndo not each require a separate continuation.\n",
)

export type ResponseSteerPendingEventSchema = typeof ResponseSteerPendingEventSchema.infer

