export const UsageAudioTranscriptionsResultSchema = type({
  object: "'organization.usage.audio_transcriptions.result'",
  seconds: type('bigint | number.integer')
    .or(/^-?\d+$/)
    .pipe((data) => BigInt(data))
    .narrow(
      (data, ctx) =>
        (data >= -9223372036854775808n && data <= 9223372036854775807n) || ctx.mustBe('an int64'),
    )
    .describe('The number of seconds processed.'),
  num_model_requests: type('number.integer').describe('The count of requests made to the model.'),
  'project_id?': type(
    type('string').describe(
      'When `group_by=project_id`, this field provides the project ID of the grouped usage result.',
    ),
  ).or('null'),
  'user_id?': type(
    type('string').describe(
      'When `group_by=user_id`, this field provides the user ID of the grouped usage result.',
    ),
  ).or('null'),
  'api_key_id?': type(
    type('string').describe(
      'When `group_by=api_key_id`, this field provides the API key ID of the grouped usage result.',
    ),
  ).or('null'),
  'model?': type(
    type('string').describe(
      'When `group_by=model`, this field provides the model name of the grouped usage result.',
    ),
  ).or('null'),
}).describe('The aggregated audio transcriptions usage details of the specific time bucket.')

export type UsageAudioTranscriptionsResultSchema = typeof UsageAudioTranscriptionsResultSchema.infer

