export const ExpiresAfterParamSchema = type({
  anchor: type("'created_at'").describe(
    'Base timestamp used to calculate expiration. Currently fixed to `created_at`.',
  ),
  seconds: type('bigint | number.integer')
    .or(/^-?\d+$/)
    .pipe((data) => BigInt(data))
    .narrow(
      (data, ctx) =>
        (data >= -9223372036854775808n && data <= 9223372036854775807n) || ctx.mustBe('an int64'),
    )
    .narrow((data, ctx) => data >= 1n || ctx.mustBe('at least 1'))
    .narrow((data, ctx) => data <= 600n || ctx.mustBe('at most 600'))
    .describe('Number of seconds after the anchor when the session expires.'),
}).describe('Controls when the session expires relative to an anchor timestamp.')

