export type ImageDetailParamSchema = typeof ImageDetailParamSchema.infer

export const DecisionInputImageSchema = type({
  image_url: type('string')
    .and(/^(data:|https?:\/\/)/)
    .narrow((data, ctx) => [...data].length >= 0 || ctx.mustBe('at least 0 characters'))
    .narrow(
      (data, ctx) => [...data].length <= 1073741824 || ctx.mustBe('at most 1073741824 characters'),
    )
    .describe('A base64-encoded image in a data URL or a publicly accessible HTTP(S) image URL.'),
  'detail?': type(ImageDetailParamSchema)
    .or('null')
    .describe(
      "The image detail level, using the selected model's image profile. Defaults to auto.",
    ),
  'prompt_cache_breakpoint?': type(
    type({
      mode: type("'explicit'").describe('The breakpoint mode. Always `explicit`.'),
      '+': 'reject',
    }),
  )
    .or('null')
    .describe(
      "Marks the exact end of a reusable prompt prefix. The breakpoint inherits its TTL from the request's `prompt_cache_options.ttl`; the boundary is not rounded to a token block.",
    ),
  type: "'input_image'",
  '+': 'reject',
}).describe(
  'An image provided as a base64 data URL or a publicly accessible HTTP(S) URL. File IDs are not supported.',
)

export type DecisionInputImageSchema = typeof DecisionInputImageSchema.infer

